# Idea: Use a binary indexed tree with coordinate compression to find the k-th smallest element
def solve(nums, k):
    # Coordinate compression
    sorted_unique = sorted(set(nums))
    rank = {v: i+1 for i, v in enumerate(sorted_unique)}
    size = len(sorted_unique)

    # Binary indexed tree (Fenwick Tree)
    class BIT:
        def __init__(self, size):
            self.tree = [0] * (size + 1)

        def update(self, idx, delta):
            while idx <= size:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    bit = BIT(size)

    # Populate BIT with frequencies
    for num in nums:
        bit.update(rank[num], 1)

    # Binary search on the value range to find the k-th smallest
    left, right = 1, size
    while left < right:
        mid = (left + right) // 2
        if bit.query(mid) < k:
            left = mid + 1
        else:
            right = mid

    return sorted_unique[left - 1]

