    for i in range(min_val, max_val + 1):
        buckets.append([])
    for num in nums:
        index = num - min_val
        if index % bucket_size == 0:
            buckets[index // bucket_size].append(num)
        else:
            buckets[index // bucket_size + 1].append(num)
    count = 0
    for bucket in buckets:
        if len(bucket) == 0:
            continue
        bucket.sort()
