            self.size = 1

        def update_size(self):
            self.size = 1
            if self.left:
                self.size += self.left.size
            if self.right:
                self.size += self.right.size

    def split(node, key):
        if not node:
            return (None, None)
        if node.val <= key:
            left, right = split(node.right, key)
            node.right = left
            node.update_size()
            return (node, right)
        else:
            left, right = split(node.left, key)
            node.left = right
            node.update_size()
            return (left, node)

