# Idea: Use a binary indexed tree (Fenwick Tree) to count occurrences and perform order statistics
class FenwickTree:
    def __init__(self, max_val):
        self.max_val = max_val
        self.tree = [0] * (self.max_val + 2)

    def update(self, index, delta):
        while index <= self.max_val:
            self.tree[index] += delta
            index += index & -index

    def query(self, index):
        res = 0
        while index > 0:
            res += self.tree[index]
            index -= index & -index
        return res

    def find_kth(self, k):
        index = 0
        bit = 1
        while bit <= self.max_val:
            temp = index + bit
            if temp <= self.max_val and self.query(temp) < k:
                index = temp
            bit <<= 1
        return index

