    # Initialize Fenwick Tree
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)
        def update(self, idx, delta=1):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx
        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res
        def find_kth(self, k):
            idx = 0
            bit = 1 << (self.n.bit_length())
            while bit > 0:
                next_idx = idx + bit
                if next_idx <= self.n and self.query(next_idx) < k:
                    idx = next_idx
                bit >>= 1
            return idx

    ft = FenwickTree(len(sorted_unique))
    # Populate the Fenwick Tree with frequencies
    for num in nums:
        idx = value_to_index[num]
        ft.update(idx)
    # Find the k-th smallest value
    return sorted_unique[ft.find_kth(k) - 1]

