    unique_vals = sorted(set(nums))
    compressed = [bisect_left(unique_vals, num) for num in nums]

    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 2)
        def update(self, idx, delta=1):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx
        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res
        def find_kth(self, k):
            idx = 1
            res = 0
            while idx <= self.n:
                if self.tree[idx] >= k:
                    idx += idx & -idx
                else:
                    k -= self.tree[idx]
                    idx += idx & -idx
            return idx - 1

    ft = FenwickTree(len(unique_vals))
    for val in compressed:
        ft.update(val + 1)

    left = 0
    right = len(unique_vals) - 1
    while left < right:
        mid = (left + right) // 2
        count = ft.query(mid + 1)
        if count < k:
            left = mid + 1
        else:
            right = mid
    return unique_vals[left]

