            return find_kth(node.left, k)
        elif k <= left_size + node.count:
            return node.value
        else:
            return find_kth(node.right, k - left_size - node.count)

    root = None
    for num in nums:
        if root is None:
            root = BSTNode(num)
        else:
            insert(root, num)

    return find_kth(root, k)

