def solve(nums, k):
    def merge_sort_and_find_kth(arr, k):
        if len(arr) <= 1:
            return arr, arr[0] if k == 1 else None

        mid = len(arr) // 2
        left, left_k = merge_sort_and_find_kth(arr[:mid], k)
        right, right_k = merge_sort_and_find_kth(arr[mid:], k)

        if left_k is not None:
            return left, left_k
        if right_k is not None:
            return right, right_k

        merged = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
        merged.extend(left[i:])
        merged.extend(right[j:])

        count = 0
        for num in merged:
            if num == merged[0]:
                count += 1
            else:
                break
        if count >= k:
            return merged, merged[0]
        else:
            return merged, merged[count - 1]

    return merge_sort_and_find_kth(nums, k)[1]

def solve(nums, k):
    min_val = min(nums)
    max_val = max(nums)
    count = {}
    for num in nums:
        count[num] = count.get(num, 0) + 1

    # Build prefix sum array
    prefix = []
    current = 0
    for i in range(min_val, max_val + 1):
        current += count.get(i, 0)
        prefix.append(current)

    # Binary search on value range to find the k-th smallest
    low, high = min_val, max_val
    while low < high:
        mid = (low + high) // 2
        # Find how many elements are <= mid
        # Since prefix is built from min_val to max_val, we can directly index
        idx = mid - min_val
        if idx >= len(prefix):
            total = prefix[-1]
        else:
            total = prefix[idx]
        if total < k:
            low = mid + 1
        else:
            high = mid
    return low

